/* Estrutura básica de uma regra CSS */
seletor {
  propriedade: valor;
  propriedade: valor;
}

/* Exemplos reais */
h1 {
  color: #6750A4;
  font-size: 2rem;
}

.card {
  background-color: #F3EDF7;
  border-radius: 12px;
  padding: 16px;
}

/* Múltiplos seletores na mesma regra */
h1, h2, h3 {
  font-family: 'Segoe UI', sans-serif;
  margin-bottom: 8px;
}

/* Seletor universal */
* { box-sizing: border-box; }

/* Descendente: todo <p> dentro de .card */
.card p { color: #444; }

/* Filho direto: apenas filhos diretos */
.menu > li { display: flex; }

/* Pseudo-classe: estado do elemento */
a:hover { color: #6750A4; }
button:focus { outline: 2px solid #6750A4; }
input:disabled { opacity: 0.5; }

/* Pseudo-elemento: parte do elemento */
p::first-line { font-weight: bold; }
.card::before {
  content: '';
  display: block;
}

/* Pixels: fixo, previsível */
.icon { width: 24px; height: 24px; }

/* rem: relativo ao root (html)
   1rem = 16px por padrão — ideal para textos */
body  { font-size: 1rem; }   /* 16px */
h1    { font-size: 2rem; }   /* 32px */

/* em: relativo ao pai — cuidado com cascata */
.card { padding: 1.5em; }

/* %: relativo ao elemento pai */
.sidebar { width: 30%; }

/* Viewport: relativo à janela */
.hero   { height: 100vh; }
.banner { width: 100vw; }

/* min / max para responsividade */
.container {
  width: 100%;
  max-width: 1200px;
}

/* Padding: espaço interno (entre conteúdo e borda) */
.card {
  padding: 24px;           /* todos os lados */
  padding: 16px 24px;      /* top/bottom | left/right */
  padding: 8px 16px 8px 24px; /* top right bottom left */
}

/* Margin: espaço externo (afasta vizinhos) */
.section {
  margin-bottom: 32px;
}

/* Centralizar bloco com margin auto */
.container {
  max-width: 960px;
  margin: 0 auto;
}

/* Centralizar texto */
.hero-title {
  text-align: center;
}

/* 1. Declarar no :root (escopo global) */
:root {
  --color-primary:    #6750A4;
  --color-surface:    #F3EDF7;
  --color-on-surface: #1C1B1F;

  --font-size-base:   1rem;
  --font-size-title:  1.5rem;

  --radius-card:      12px;
  --spacing-md:       16px;
  --spacing-lg:       24px;
}

/* 2. Usar com var() */
.card {
  background: var(--color-surface);
  border-radius: var(--radius-card);
  padding: var(--spacing-lg);
  color: var(--color-on-surface);
}

.btn-primary {
  background: var(--color-primary);
  font-size: var(--font-size-base);
}

/* Peso 0,0,1 — tag */
p { color: black; }

/* Peso 0,1,0 — classe */
.texto { color: blue; }

/* Peso 0,1,1 — classe + tag */
p.texto { color: green; }

/* Peso 1,0,0 — ID */
#intro { color: red; }

/* Inline (HTML): 1,0,0,0 — vence tudo exceto !important */
/* <p style="color: orange"> */

/* !important — anula o cálculo */
.aviso { color: purple !important; }

/* Mesmo elemento com as 4 regras acima:
   Renderiza: purple (!important)
   Sem !important: renderizaria red (#intro) */
